#include <cstddef>
#include <cstdint>

struct Record {                 // frozen: reordering these members breaks the ABI
    std::uint32_t id;
    double score;
    std::uint32_t flags;
};

namespace probe {
constexpr std::size_t size();             // sizeof(Record)
constexpr std::size_t align();            // alignof(Record)
constexpr std::size_t offset_id();        // offsetof(Record, id)
constexpr std::size_t offset_score();     // offsetof(Record, score)
} // namespace probe

